{"explanation":"In y = a(x − h)² + k, the vertex is (h, k): h shifts the parabola horizontally, and k shifts it vertically. The parameter a controls its opening: positive opens upward, negative opens downward, and larger |a| makes it narrower; a = 0 gives a horizontal line. Drag the yellow vertex to change h and k, and drag the orange point vertically to change a.","manimCode":"const ax = new Axes({ xRange: [-5, 5, 1], yRange: [-4, 4, 1], xLength: 10, yLength: 4.8, tips: false });
let a = 0.7;
let h = -0.8;
let k = -0.7;
const offset = 1.4;
let curve = null;

const title = new MathTex({ latex: 'y = a(x-h)^2+k', color: WHITE });
await title.waitForRender();
title.moveTo([0, 3.25, 0]);
const readout = new Text({ text: '', fontSize: 23, color: WHITE });
readout.moveTo([0, 2.7, 0]);
const hint = new Text({ text: 'Drag yellow: vertex (h, k)   |   Drag orange vertically: a', fontSize: 20, color: GRAY });
hint.moveTo([0, -3.35, 0]);
const effect = new Text({ text: '', fontSize: 22, color: BLUE });
effect.moveTo([0, -2.85, 0]);

const symmetry = new DashedLine({ start: ax.c2p(h, -4), end: ax.c2p(h, 4), color: GRAY });
const rise = new Line({ start: ax.c2p(h + offset, k), end: ax.c2p(h + offset, k + a * offset * offset), color: ORANGE });
const run = new DashedLine({ start: ax.c2p(h, k), end: ax.c2p(h + offset, k), color: GRAY });
const vertex = new Dot({ point: ax.c2p(h, k), radius: 0.14, color: YELLOW });
const bend = new Dot({ point: ax.c2p(h + offset, k + a * offset * offset), radius: 0.14, color: ORANGE });
const vertexLabel = new Text({ text: '(h, k)', fontSize: 20, color: YELLOW });
const bendLabel = new Text({ text: 'change a', fontSize: 18, color: ORANGE });
scene.add(ax, title, readout, symmetry, run, rise, vertex, bend, vertexLabel, bendLabel, effect, hint);

function update() {
  const f = x => a * (x - h) * (x - h) + k;
  // Rebuild the plotted domain so the visible parabola stays inside the axes.
  let left = -5;
  let right = 5;
  if (Math.abs(a) > 0.00001) {
    const boundary = a > 0 ? 4 : -4;
    const radius = Math.sqrt((boundary - k) / a);
    left = Math.max(-5, h - radius);
    right = Math.min(5, h + radius);
  }
  if (curve) scene.remove(curve);
  curve = ax.plot(f, { xRange: [left, right, 0.025], color: BLUE });
  curve.setStrokeWidth(4);
  scene.add(curve);
  symmetry.setStart(ax.c2p(h, -4));
  symmetry.setEnd(ax.c2p(h, 4));
  run.setStart(ax.c2p(h, k));
  run.setEnd(ax.c2p(h + offset, k));
  rise.setStart(ax.c2p(h + offset, k));
  rise.setEnd(ax.c2p(h + offset, f(h + offset)));
  vertex.moveTo(ax.c2p(h, k));
  bend.moveTo(ax.c2p(h + offset, f(h + offset)));
  const vp = ax.c2p(h, k);
  const bp = ax.c2p(h + offset, f(h + offset));
  vertexLabel.moveTo([vp[0] - 0.48, vp[1] - 0.32, 0]);
  bendLabel.moveTo([bp[0], bp[1] + (a >= 0 ? 0.3 : -0.3), 0]);
  readout.setText('a = ' + a.toFixed(2) + '     h = ' + h.toFixed(2) + '     k = ' + k.toFixed(2));
  if (Math.abs(a) < 0.00001) {
    effect.setText('a = 0: horizontal line y = k');
  } else {
    effect.setText((a > 0 ? 'Opens upward' : 'Opens downward') + '   |   larger |a| = narrower');
  }
  // Keep the handles and their labels above the newly plotted curve.
  scene.remove(vertex, bend, vertexLabel, bendLabel);
  scene.add(vertex, bend, vertexLabel, bendLabel);
}
update();

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
makeDraggable(vertex, scene, { onDrag: (mob, pos) => {
  const coordinates = ax.pointToCoords(pos);
  h = clamp(coordinates[0], -3, 3);
  k = clamp(coordinates[1], -1.2, 1.2);
  update();
} });
makeDraggable(bend, scene, { onDrag: (mob, pos) => {
  const coordinates = ax.pointToCoords(pos);
  a = clamp((coordinates[1] - k) / (offset * offset), -1.2, 1.2);
  if (Math.abs(a) < 0.025) a = 0;
  update();
} });

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addButton({ label: 'Reset', onClick: () => {
  a = 0.7; h = -0.8; k = -0.7;
  update();
} });
await scene.wait(999999);"}

